import{_ as t,o as a,c as n,a2 as o}from"./chunks/framework.BXzK3EA4.js";const u=JSON.parse('{"title":"Agent by Example","description":"","frontmatter":{},"headers":[],"relativePath":"new-features/agent/examples.md","filePath":"new-features/agent/examples.md"}'),s={name:"new-features/agent/examples.md"};function r(i,e,h,d,l,c){return a(),n("div",null,[...e[0]||(e[0]=[o(`<h1 id="agent-by-example" tabindex="-1">Agent by Example <a class="header-anchor" href="#agent-by-example" aria-label="Permalink to &quot;Agent by Example&quot;">​</a></h1><p>This page is a set of prompts that work, and what each one gives back. Every example here was typed into a running Tradeboard instance and the description is of what actually came out. Start at the top: the first two sections cover what most people try first.</p><p>Type into the box at the bottom of <code>/agent</code>, which prompts you to &quot;Ask about your positions, a symbol, a strategy or a workflow&quot;. Enter sends and Shift with Enter starts a new line, except while an input method editor is mid-composition, where Enter commits the composition instead. The same box, narrower, sits on the right of <code>/trading</code> under the heading &quot;Assistant&quot;.</p><h2 id="quotes-and-instruments" tabindex="-1">Quotes and Instruments <a class="header-anchor" href="#quotes-and-instruments" aria-label="Permalink to &quot;Quotes and Instruments&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>get the stock price of reliance</span></span></code></pre></div><p>One tool call, and the answer is a card rather than a sentence: the symbol with its exchange and instrument type, the company name and lot size, the last price with the change and percentage from the previous close, an intraday chart, the day range, the 52 week range and how far price sits below the 52 week high, open, high, low, previous close, volume, bid, ask and spread, and five levels of the order book. Under it are Buy and Sell controls, captioned &quot;Writes the request into the message box. Nothing is ordered until you send it and approve it.&quot;</p><p>You do not need to name the exchange for a well known equity. Name it when the symbol is ambiguous, as in <code>get the stock price of infy on NSE</code>.</p><p>A card that is streaming carries a LIVE badge. Reopen the conversation tomorrow and the same card re-reads market data on the spot, so it will read DELAYED with &quot;Not ticking. Last read ...&quot;, or CLOSED with &quot;Market closed. Last read ...&quot;. It never shows a stale number without saying so.</p><h2 id="charts-and-history" tabindex="-1">Charts and History <a class="header-anchor" href="#charts-and-history" aria-label="Permalink to &quot;Charts and History&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>plot the last 10 days of RELIANCE</span></span></code></pre></div><p>A candlestick chart drawn with the same charting library as <code>/trading</code>, captioned with the bar count and the date range it actually covers. Asking for 10 days across a normal week returns 8 bars, and the answer says so: &quot;covering 26 Aug to 4 Sep 2026 (8 trading sessions)&quot;. It does not invent two sessions to match the number you asked for.</p><p>Ask for the interval by name, because the default is daily: <code>plot RELIANCE 15 minute candles for the last 3 sessions</code>.</p><h2 id="indicators" tabindex="-1">Indicators <a class="header-anchor" href="#indicators" aria-label="Permalink to &quot;Indicators&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>reliance hourly with supertrend 3,10 and macd in table format</span></span></code></pre></div><p>A ten row table with Time, Close, Supertrend, Trend, MACD, Signal and Histogram, timestamped in IST, followed by two sentences reading the result. The indicators are computed by <code>tradeboard.ta</code> over real candles the tool fetched, so the numbers are the platform&#39;s own rather than the model&#39;s arithmetic.</p><p>Two things in that prompt are doing work. &quot;3,10&quot; gives the parameters, so the answer states which it used rather than picking one silently. &quot;in table format&quot; is what turns a paragraph into a table; ask for it whenever you want to read values rather than a conclusion.</p><h2 id="options-and-payoffs" tabindex="-1">Options and Payoffs <a class="header-anchor" href="#options-and-payoffs" aria-label="Permalink to &quot;Options and Payoffs&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>show me the NIFTY option chain 3 strikes either side of ATM</span></span></code></pre></div><p>The chain as a table of Strike, CE LTP, CE OI, PE LTP and PE OI with the ATM row marked, preceded by a line naming the expiry it resolved to, the spot and the lot size. Say &quot;monthly expiry&quot; or name a date if you do not want the nearest one.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>payoff graph of a NIFTY short straddle</span></span></code></pre></div><p>A payoff card. The legs are listed first with side, lots, the full contract symbol and the premium each was priced at, then a strip of net credit, both breakevens, maximum profit and maximum loss, then the curve itself with an expiry line and a T+0 line, the spot marked, and a shaded one and two standard deviation band. Under the chart is a scenario table of underlying price against profit at expiry and at T+0. Maximum loss on a short straddle reads &quot;Unlimited loss&quot; rather than a number.</p><p>The tool resolves the strikes and prices the legs itself. You can pin them instead: <code>payoff for NIFTY 08SEP26 23950 CE short and 23950 PE short, 1 lot each</code>.</p><h2 id="live-streaming" tabindex="-1">Live Streaming <a class="header-anchor" href="#live-streaming" aria-label="Permalink to &quot;Live Streaming&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>stream me live prices for RELIANCE, INFY and TCS</span></span></code></pre></div><p>A Live Quote card holding all three, each row with last price, change, open, high, low, previous close, volume, bid and ask. The card subscribes your browser to the feed and updates in place. Each row is labelled with how fresh it is: &quot;TICK 2M AGO&quot; for one that is ticking, or &quot;SNAPSHOT&quot; with a timestamp for one that is not.</p><p>The card as a whole carries the state of the feed behind it and says what that state means in a line underneath: LIVE while ticks are arriving, POLLING when the socket is gone and the values are coming from REST polls instead, CLOSED when the session is shut (&quot;Market closed, so these are the ... snapshot values&quot;), and NOT CONNECTED when there is no feed at all. Off screen or past the live-card limit it stops streaming on purpose and offers you the way back. It never shows a still price as though it were a moving one.</p><h2 id="web-research" tabindex="-1">Web Research <a class="header-anchor" href="#web-research" aria-label="Permalink to &quot;Web Research&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>what did the RBI decide at its latest meeting</span></span></code></pre></div><p>The answer names the meeting and its dates, lists the decisions, and ends with its sources as real links you can click. It also attributes rather than asserts: &quot;according to the research provider&quot;. Web results are treated as lower trust than the platform&#39;s own data, and the answer is written that way.</p><p>Web search is on by default and lives in the &quot;+&quot; menu at the left of the composer. Turn it off there for a conversation that should stay on your own data; the search tools are then not built into the request at all, and the composer says &quot;Web search is off for this conversation.&quot;</p><h2 id="generating-a-strategy-script" tabindex="-1">Generating a Strategy Script <a class="header-anchor" href="#generating-a-strategy-script" aria-label="Permalink to &quot;Generating a Strategy Script&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>write a python script to fetch SBIN history</span></span></code></pre></div><p>A Python code block, labelled with its language and carrying a Copy control, with no line numbers and no inner scroll box. It uses the <code>tradeboard</code> SDK (<code>from tradeboard import api</code>), reads the API key and host from environment variables rather than hard coding them, and opens with a comment naming a path under <code>strategies/scripts/</code>.</p><p>Generating a script and installing one are separate steps. The agent can write the file into <code>strategies/scripts/</code> only if you approve that call, and it never starts what it writes. See <a href="./../python-strategy-hosting.html">Python Strategy Hosting</a> for what happens to a script once it is there.</p><h2 id="reading-an-answer" tabindex="-1">Reading an Answer <a class="header-anchor" href="#reading-an-answer" aria-label="Permalink to &quot;Reading an Answer&quot;">​</a></h2><p>A turn is more than the paragraph at the end of it, and three parts of what you see are worth knowing.</p><p><strong>Thinking, then tokens.</strong> While nothing has arrived yet the turn shows a &quot;Thinking&quot; indicator. On a model that emits its reasoning, a collapsed <strong>Reasoning</strong> block appears above the answer; open it to read what the model worked through, or leave it shut, which is the default.</p><p><strong>The tool calls.</strong> Every turn that touched a tool carries a collapsed timeline saying how many calls it made and, while it is running, which one is running now. Open it and you get one named row per call with the time it took, and each row expands to the arguments it was given, as formatted JSON, and the result it returned. Nothing in there is treated as markup: every value is rendered as text, so a tool result carrying HTML or somebody else&#39;s instructions is displayed rather than acted on. This is where you check that a number in the answer came from a tool and not from the model.</p><p><strong>Stop.</strong> While a turn runs the send button becomes a stop button, and the line under the composer says &quot;Running. Stop ends the turn on the server, not just here.&quot; That distinction matters: a run you merely stopped watching would still be running and still be billed.</p><h2 id="the-chart-agent-on-trading" tabindex="-1">The Chart Agent on /trading <a class="header-anchor" href="#the-chart-agent-on-trading" aria-label="Permalink to &quot;The Chart Agent on /trading&quot;">​</a></h2><p>Open it from the right rail of the charting terminal: the third button, under Watchlist and Option chain, labelled <strong>Assistant</strong>. Press it again or press Escape to close it, drag its inner edge to change the width, and both the width and the fact it was open are remembered next time.</p><p>The panel reads the chart you are looking at: its symbol, its interval, its bars and your own drawings. It reads them at the moment you press send, so change the symbol first and then ask. In a multi-chart layout it reads the focused pane, so click the pane you mean before asking about it.</p><p>Four chips sit above the box: Analyse this chart, Draw demand and supply, Candlestick patterns, Read my drawings. A chip fills the box, it does not send, so you can narrow the question before you commit.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Draw the demand and supply zones on this chart.</span></span></code></pre></div><p>Two boxes appear on the real chart, labelled demand and supply, and the answer names the price band of each and the swing it came from with its IST timestamp: &quot;Demand: 429.65 to 431.40, from the 13:05 IST swing low.&quot; The prices come from the candles, not from the model. They are ordinary drawings once placed, and <code>clear the zones you just drew</code> takes them off again.</p><p>The panel has no model picker; it runs whichever model is your configured default. It also has no order tools at all, which is why its empty state says &quot;It places no orders here.&quot; Its thread is not the same thing as a conversation on <code>/agent</code>: it starts fresh when you reload the page and does not appear in the <code>/agent</code> conversation list.</p><h2 id="placing-an-order" tabindex="-1">Placing an Order <a class="header-anchor" href="#placing-an-order" aria-label="Permalink to &quot;Placing an Order&quot;">​</a></h2><p>Order tools are only ever offered on <code>/agent</code>, never on the chart panel.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>buy 1 share of RELIANCE on NSE at market, MIS</span></span></code></pre></div><p>The run stops. In place of an answer you get an amber panel reading &quot;This turn is waiting for your approval.&quot;, the name of the tool it wants to call, the exact arguments it wants to call it with, and two buttons:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>place_order</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>  &quot;symbol&quot;: &quot;RELIANCE&quot;,</span></span>
<span class="line"><span>  &quot;exchange&quot;: &quot;NSE&quot;,</span></span>
<span class="line"><span>  &quot;action&quot;: &quot;BUY&quot;,</span></span>
<span class="line"><span>  &quot;quantity&quot;: 1,</span></span>
<span class="line"><span>  &quot;product&quot;: &quot;MIS&quot;,</span></span>
<span class="line"><span>  &quot;price_type&quot;: &quot;MARKET&quot;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Nothing has been sent. No order exists anywhere. Read the arguments, because they are the order, and the only thing between them and your broker is the button you press next.</p><p>Press Reject and the run resumes with &quot;Order not placed. You rejected the approval for this order:&quot; and a summary of what it did not do. Press Approve and the tool runs, the risk limits are checked inside it, and the order goes wherever the platform is pointed.</p><p>That last part is the one to be sure of before you approve anything. With the platform in live mode, an approved order is sent to your broker with real money. With the platform in analyzer mode, an approved order reaches the sandbox instead. The <code>/agent/config</code> trading panel states whichever of the two applies to your instance. Every order tool behaves this way: placing, modifying, cancelling, cancelling all, closing a position and closing all positions each pause for approval, individually, every time.</p><h2 id="getting-better-answers" tabindex="-1">Getting Better Answers <a class="header-anchor" href="#getting-better-answers" aria-label="Permalink to &quot;Getting Better Answers&quot;">​</a></h2><ul><li><strong>Name the exchange when the symbol is ambiguous.</strong> &quot;SBIN on NSE&quot; resolves in one step; a bare symbol that exists on two exchanges costs a round trip and may resolve to the one you did not mean.</li><li><strong>Ask for a table when you want values.</strong> &quot;in table format&quot; is the difference between a paragraph summarising a trend and ten rows you can read down.</li><li><strong>Give indicator parameters in the prompt.</strong> &quot;supertrend 3,10&quot; is answered with those; &quot;supertrend&quot; is answered with a default the answer then has to tell you about.</li><li><strong>Turn web search on for anything current</strong>, and off for anything that should come only from your own platform.</li><li><strong>Raise the reasoning effort for analysis, not for lookup.</strong> The control sits beside the model name in the composer: Default is the model&#39;s own, Low is fastest, Medium is balanced, High is deepest. A price lookup gains nothing from High; reading a chart&#39;s structure or weighing an options position does. The control appears only on models that take a reasoning effort.</li><li><strong>Ask two questions rather than one enormous one.</strong> A run stops after 25 tool calls, so a sweep across a long list of instruments is better split than crammed into a single prompt.</li></ul><h2 id="conversation-mechanics" tabindex="-1">Conversation Mechanics <a class="header-anchor" href="#conversation-mechanics" aria-label="Permalink to &quot;Conversation Mechanics&quot;">​</a></h2><p><strong>The list on the left.</strong> A thread is titled from the first 80 characters of your first message, and the rows are ordered by when each was last used. New chat creates nothing until you send something, so an abandoned thread leaves no empty row. The list collapses out of the way with the control at its top. Opening a thread, deleting one and New chat are all disabled while a turn is running, because switching thread mid-answer would discard the answer.</p><p><strong>Delete.</strong> The bin on a row asks first, and says what it does: the conversation and every message in it go, and it cannot be undone. Audit rows for orders are kept, because they are a trade record and they outlive the conversation the trade was typed into.</p><p><strong>Edit a question in place.</strong> Hover a question you have sent and a pencil appears. The bubble becomes a text box with Cancel and Send, and a note saying &quot;Sending replaces this message and discards the reply below it.&quot; That is exactly what happens: change &quot;reliance&quot; to &quot;infy&quot;, send, and the RELIANCE answer is gone, replaced by an INFY one. There is no confirmation dialog, because the note is the warning.</p><p><strong>Retry and copy.</strong> Hover an answer for a copy control and, on a turn that failed, a retry control that asks the last question again. Copy takes the raw text of the answer, not the rendered page.</p><p><strong>Attach files.</strong> Use &quot;Attach files&quot; in the &quot;+&quot; menu, drag a file onto the composer, or paste one straight from the clipboard, which is how a screenshot gets in. Up to 4 files per turn, 4 MB each and 8 MB in total, covering PNG, JPEG, GIF and WebP images and plain text, CSV, TSV, Markdown, JSON, Python, XML and HTML. A text file over 20,000 characters is refused with its size named rather than quietly truncated. Attachments are replayed into context on later turns of the same conversation, which is the reason for the caps. On a model that cannot see images, attaching is withheld and the menu says so, naming the model.</p><p><strong>Attach the chart itself.</strong> On <code>/trading</code> only, the &quot;+&quot; menu also offers &quot;Attach chart screenshot&quot;, which photographs the pane your question is about. The chat page has no chart, so it does not offer this.</p><p><strong>Every turn is costed.</strong> Under each answer is its token usage, and the header carries the running total for the whole conversation. A turn billed to an API key shows a dollar figure. A turn that ran on a ChatGPT Plus or Pro plan reads &quot;included in your ChatGPT plan&quot;, because it consumed plan quota rather than being free. A model with no published price shows a dash. None of the three ever renders as <code>$0.00</code>.</p><p><strong>Conversations persist.</strong> They reopen with their cards, charts and tables intact. The model is given the last eight turns of the thread as context rather than all of it, so a very long conversation will not remember its own beginning; say the thing again, or start a fresh thread for a fresh subject.</p><h2 id="operational-boundaries" tabindex="-1">Operational Boundaries <a class="header-anchor" href="#operational-boundaries" aria-label="Permalink to &quot;Operational Boundaries&quot;">​</a></h2><ul><li>Prices, chains, candles and depth come from your broker and your entitlement. Nothing on this page changes what your account is allowed to see.</li><li>An intraday card, a live stream and an option chain are only as current as the feed behind them. The cards say when they are not streaming; believe the label rather than the number.</li><li>An approved order is a real order in live mode. Approval is the only gate, and it cannot be turned off for individual tools.</li><li>The chart panel is offered no order tools, so nothing typed into it can place an order. Order requests belong on <code>/agent</code>.</li><li>Web search results are third party text. The agent labels them and cites them so you can check them, which is worth doing before acting on one.</li><li>A generated script or workflow is a draft for you to read. Nothing generated starts itself.</li><li>Answers depend on the model you have configured. A cheaper or older model will call fewer tools and read the results less carefully than the examples above.</li></ul><h2 id="see-also" tabindex="-1">See Also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See Also&quot;">​</a></h2><ul><li><a href="./README.html">Agent</a> for the overview and the three surfaces.</li><li><a href="./voice.html">Voice Agent</a> for Vega, the microphone on <code>/agent</code>.</li><li><a href="./capabilities.html">What the Agent Can Do</a> for the full tool list and the order path.</li><li><a href="./configuration.html">Agent Configuration</a> for models, keys, the trading switch and web search.</li><li><a href="./chatgpt-subscription.html">ChatGPT Subscription</a> for the plan billing path.</li><li><a href="./../trading-terminal.html">Chart Trading Terminal</a> for the chart the panel sits beside.</li></ul>`,69)])])}const g=t(s,[["render",r]]);export{u as __pageData,g as default};
